// generated by scripts/export_constants.py — do not edit
//
// Source of truth: src/trafficlens/core/constants.py
// Change a value there and run the exporter; tests/test_constants_sync.py
// fails while this file and that one disagree.

// Tolerance for geometric comparisons (cross-product sign, denominator
// magnitude) in trafficlens.core.geometry. Coordinates are pixel positions,
// so 1e-9 is far below any sub-pixel noise a detector or tracker could ever
// produce -- it only guards against floating-point rounding, not real
// ambiguity in the input.
export const GEOMETRY_EPS = 1e-09;

// Maximum acceptable value of the rank/uniqueness diagnostic
// trafficlens.core.homography._dlt_condition_number computes from the
// Hartley-normalized DLT design matrix, used by RoadPlane.validate() to
// detect a geometrically degenerate correspondence set (collinear points, a
// duplicated point, or any configuration close to one) without penalising a
// precise survey. The diagnostic is sigma_1/sigma_8 of the design matrix's
// singular values for BOTH the exactly-4-point case (8x9 matrix, 8 singular
// values total, sigma_8 is the last one) and the 5-or-more-point case (2Nx9
// matrix, 9 singular values, sigma_9 -- the smallest -- is excluded because
// it measures fit residual/noise, not geometry; see that function's
// docstring for why excluding it matters).
//
// Measured on real synthetic configurations, both sides of the threshold,
// for both point counts (name kept "CONDITION_NUMBER" despite the sigma_8
// vs sigma_9 distinction: it is still literally sigma_1 divided by another
// singular value of the same matrix, just the correct one):
//   - 4-point healthy trapezoid: ~7.93. Threshold / healthy = ~1261x margin.
//   - 4-point near-degenerate (one point nudged 1mm toward collinear with
//     the other three): ~56216. Near-degenerate / threshold = ~5.6x margin
//     -- narrower than the healthy side, but still clearly separated.
//   - 5-point healthy, well-spread survey, Gaussian pixel noise sigma in
//     {0.1, 0.25, 0.5, 1.0, 2.0}px, 30 trials each (see
//     tests/test_homography.py::test_precise_surveys_are_never_rejected_as_degenerate):
//     ~4.6-4.7 across every noise level tested, essentially flat -- this
//     diagnostic does not scale with survey precision the way the excluded
//     sigma_9 did. Threshold / worst observed (~4.66) = ~2146x margin.
//   - 5-point genuinely degenerate (4 of the 5 points collinear, 1 off the
//     line -- the minimum degeneracy that leaves no non-degenerate 4-point
//     subset among the 5): ~1.27e16. Degenerate / threshold = ~1.27e12x
//     margin.
// 10000.0 sits comfortably inside every one of these gaps; the narrowest
// margin on either point count is the 4-point near-degenerate case (~5.6x),
// which is why that fixture nudges a point by a full 1mm rather than a
// smaller amount that might land closer to the threshold.
export const HOMOGRAPHY_MAX_RANK_CONDITION_NUMBER = 10000.0;

// Default maximum acceptable mean reprojection error, in metres, for
// RoadPlane.validate() to accept a calibration. 0.5m mirrors the threshold a
// corrupted single-point survey error is expected to exceed: a mean error
// this large means an object's reported plane position -- and therefore its
// speed -- cannot be trusted to better than half a metre, which is too
// coarse for confident lane-level speed enforcement.
export const HOMOGRAPHY_MAX_MEAN_ERROR_M = 0.5;

// Default minimum per-class confidence score trafficlens.detect.base.decode_yolo
// keeps a raw prediction at, before NMS runs. 0.25 is the long-standing YOLO
// default (YOLOv3 through ultralytics' own predict CLI), low enough to leave
// real-but-uncertain detections in for NMS and downstream tracking to sort
// out, high enough to drop the long tail of near-zero background scores.
export const DETECT_DEFAULT_CONF = 0.25;

// Default IoU threshold trafficlens.detect.base.nms uses to suppress a
// lower-score duplicate box in favour of a higher-score one for the same
// class. 0.45 is the classic YOLO NMS default (YOLOv5 through v8): tight
// enough to collapse near-duplicate boxes on one vehicle, loose enough not
// to merge two genuinely distinct, closely-spaced vehicles into one.
export const DETECT_DEFAULT_NMS_IOU = 0.45;

// Default square side, in pixels, trafficlens.detect.base.letterbox resizes
// and pads a frame to before it is handed to a YOLO11 model. 640 is the
// input resolution yolo11n.pt/yolo11s.pt/yolo11m.pt in this repo were
// trained and exported at -- confirmed by the ONNX export's own reported
// output shape (1, 84, 8400) for imgsz=640, since 8400 = (640/8)^2 +
// (640/16)^2 + (640/32)^2, the three detection-head stride grids summed.
export const DETECT_DEFAULT_INPUT_SIZE = 640;

// Grey value trafficlens.detect.base.letterbox pads a frame's borders with,
// so padding never biases a detection toward any class. 114 is the value
// YOLOv5 introduced and ultralytics (and therefore YOLO11) has used ever
// since -- the same value every checkpoint in this repo was trained
// against, so padding with anything else would shift the input distribution
// the model actually saw during training.
export const LETTERBOX_PAD_VALUE = 114;

// --- Kalman filter (trafficlens.track.kalman) --------------------------------
// All tunables of the constant-velocity box filter live here so the later
// TypeScript mirror reads the exact same values; kalman.py itself contains
// no numeric tunables.

// Base standard deviation of POSITION-like state components (cx, cy, h) as a
// fraction of the box height h. Height is a proxy for distance from the
// camera: a taller box is a nearer object, which moves more pixels per frame,
// so its uncertainty in pixels should be proportionally larger. 1/20 = 0.05
// is the weight the original DeepSORT filter shipped with and has been the
// de-facto standard for xyah box filters since.
export const KALMAN_STD_WEIGHT_POSITION = 0.05;

// Base standard deviation of VELOCITY-like state components (vx, vy, vh) as a
// fraction of the box height, per frame. 1/160 = 0.00625 (DeepSORT's value):
// velocities change far more slowly than positions jitter, so the process
// trusts the constant-velocity model 8x more (0.05 / 0.00625) than it trusts
// any single position.
export const KALMAN_STD_WEIGHT_VELOCITY = 0.00625;

// Multiplier on the position weight for the INITIAL position variance in
// initiate(): the first box comes from a single unconfirmed detection, so it
// is trusted less (2x the running std) than a measurement arriving during
// steady-state tracking.
export const KALMAN_INIT_POSITION_STD_FACTOR = 2.0;

// Multiplier on the velocity weight for the INITIAL velocity variance in
// initiate(): velocities start at exactly 0 with no evidence at all, so
// their std is inflated 10x -- the first two or three measurements then set
// the velocity almost entirely on their own.
export const KALMAN_INIT_VELOCITY_STD_FACTOR = 10.0;

// Standard deviation of the aspect-ratio (a = w/h) state used for the
// initial variance and the per-step process noise. Aspect ratio is
// dimensionless and near-constant for a rigid vehicle, so its uncertainty
// is a small absolute value rather than height-scaled. 1e-2 per DeepSORT.
export const KALMAN_ASPECT_STD = 0.01;

// Standard deviation of the aspect-ratio VELOCITY (va) process noise per
// step. Aspect ratio should barely drift at all frame-to-frame, hence three
// orders of magnitude below KALMAN_ASPECT_STD. 1e-5 per DeepSORT.
export const KALMAN_ASPECT_VELOCITY_STD = 1e-05;

// Standard deviation of the aspect-ratio MEASUREMENT noise in update().
// Detector aspect ratios jitter much more than the true aspect drifts
// (partial occlusion clips box width), so the measurement is trusted 10x
// less (1e-1) than the state's own process noise (1e-2). Per DeepSORT.
export const KALMAN_ASPECT_MEASUREMENT_STD = 0.1;

// 95% quantile of the chi-square distribution with 4 degrees of freedom
// (one DOF per measured component: cx, cy, a, h). A squared Mahalanobis
// gating distance above this value means the measurement has under a 5%
// chance of belonging to the track under Gaussian assumptions; the tracker
// (Task 7) refuses to associate such pairs. scipy.stats.chi2.ppf(0.95, 4)
// = 9.487729036781154, conventionally quoted as 9.4877.
export const KALMAN_GATING_CHI2_95_4DOF = 9.4877;

// --- Multi-object tracker (trafficlens.track.tracker) ------------------------
// All tunables of the two-stage tracker live here so the later TypeScript
// mirror reads the exact same values; tracker.py itself contains no numeric
// tunables. Each is the default of the corresponding Tracker() constructor
// parameter.

// Detection score at or above which (inclusive) a detection counts as HIGH
// confidence: eligible for the first association stage against every live
// track, and the only kind of detection allowed to start a new track. 0.6
// follows ByteTrack's published track_thresh for vehicle-scale objects:
// high enough that a track is only ever born from a detection the model is
// genuinely sure about, low enough not to starve the tracker on ordinary
// footage.
export const TRACK_HIGH_CONF = 0.6;

// Detection score at or above which (inclusive) a detection enters the LOW
// confidence band [TRACK_LOW_CONF, TRACK_HIGH_CONF) used by the second
// association stage to keep an occluded, already-confirmed track alive.
// Detections below this are discarded entirely. 0.1 is ByteTrack's floor:
// under it, boxes are overwhelmingly background noise that would only feed
// false re-associations.
export const TRACK_LOW_CONF = 0.1;

// IoU floor for detection-to-track association, in BOTH stages: a pair is
// eligible only when IoU(predicted box, detection box) >= this value,
// implemented as an assignment cost of (1 - IoU) capped at max_cost
// = (1 - TRACK_MATCH_IOU). 0.8 is strict by design: with a per-frame
// Kalman prediction supplying the motion, a genuine continuation overlaps
// its predicted box almost entirely, so demanding 80% overlap rejects
// lane-neighbour confusions that a looser floor would let through.
//
// MEASUREMENT CORRECTS THAT RATIONALE, and does not confirm it either.
// The association-floor ablation in reports/robustness.json varies this
// floor from 0.8 to BASELINE_GREEDY_IOU_THRESH's 0.3 with everything else
// identical -- same degraded detection stream, same counting rule, same
// track lifecycle, same match window -- and measures, in crossing F1:
//   - undegraded, at every one of the four protocols' identity levels:
//     the two floors TIE exactly. The premise above is not contradicted
//     where the boxes are clean.
//   - frame rate 5 fps: the loose floor gains 0.6020, the largest gain
//     anywhere in the sweep. 30% dropped frames: +0.2791. Box jitter at
//     sigma = 4 px: +0.3652. So the moment the input degrades, "a genuine
//     continuation overlaps its predicted box almost entirely" is false,
//     and this floor is what turns that into lost crossings.
//   - detection dropout: the largest gain is 0.0000, and at p >= 0.20 the
//     loose floor scores 0.0252 WORSE. Whatever the engine loses under
//     dropout is a separate fault and is not diagnosed by this ablation.
// The honest summary is that nothing in this sweep measures 0.8 as better
// than 0.3 anywhere except under detection dropout: it ties clean, loses on
// three of the four degradation families, and wins on one, by 0.0252. The
// tie undegraded is not an argument for keeping it; the dropout cost is the
// only argument there is.
//
// The constant is NOT changed here, deliberately. Choosing a new floor is
// separate work needing its own baseline, and this sweep -- one clip, 17
// labelled crossings, two floors -- is not the evidence for a value. The
// weakness ships documented rather than half-fixed.
export const TRACK_MATCH_IOU = 0.8;

// Number of consecutive frames a confirmed track may go without a matched
// detection before it is dropped. A track whose time_since_update exceeds
// this dies; a gap of up to exactly this many frames survives on Kalman
// prediction alone and can re-associate. 30 frames is one second at the
// 30 fps footage this project targets -- the longest occlusion (an
// overtaking lorry, a sign gantry) worth bridging before the motion
// extrapolation itself becomes untrustworthy.
export const TRACK_MAX_AGE = 30;

// Consecutive matched frames (hits) a new track needs before it is
// CONFIRMED and appears in Tracker.update() output; until then it is
// tentative and internal, and a single missed frame kills it. 3 is the
// SORT/DeepSORT convention: two frames of agreement can still be a
// double-counted NMS artefact, three in a row almost never are.
export const TRACK_MIN_HITS = 3;

// Tolerance under which two assignment totals in
// trafficlens.track.associate.assign count as the SAME optimum, so the
// canonical lexicographic tie rule (not the solver's internals) picks
// between them. This defines the cost granularity of the association: two
// candidate assignments whose (1 - IoU) totals differ by less than 1e-6
// are treated as tied -- an IoU distinction that small has no physical
// meaning at pixel scale -- and any genuine difference at or above it is
// always respected. 1e-6 sits well clear on both sides: accumulated
// float64 summation rounding across candidate totals stays below ~1e-8
// even with barred stand-in entries (1e4 each, see associate.py) in the
// sums, while meaningful IoU-cost differences are orders of magnitude
// above it.
export const TRACK_ASSIGN_TIE_TOL = 1e-06;

// --- Speed estimation (trafficlens.analytics.speed) ---------------------------
// All tunables of the plane-space speed estimator live here so the later
// TypeScript mirror reads the exact same values; speed.py itself contains
// no numeric tunables.

// Default trailing window, in seconds, of accepted plane-space samples the
// least-squares speed fit runs over. 2.0s holds ~60 samples at the 30 fps
// footage this project targets -- enough for the fitted slope to average out
// per-frame anchor jitter -- while staying short enough that a braking or
// accelerating vehicle reads its current speed rather than a multi-second
// average; a vehicle at motorway speed covers ~50m in 2s, comfortably
// within one calibrated camera view.
export const SPEED_WINDOW_S = 2.0;

// Default minimum number of in-window accepted samples before speed_kmh
// reports a number instead of None. Two samples determine a line exactly,
// with zero residual, so any two noisy anchors would yield a confidently
// wrong slope; five samples (0.2s at 25 fps) is the point where independent
// per-frame jitter starts cancelling in the fit instead of steering it.
export const SPEED_MIN_SAMPLES = 5;

// Maximum plane-space step, in metres, a new sample may take from the last
// ACCEPTED sample of the same track before it is rejected as a bad
// detection at observe() time (never buffered), so one wild detector box
// cannot spike the speed. Physics: 250 km/h -- faster than any road vehicle
// this product will ever see -- is 69.4 m/s, which at 15 fps (the lowest
// frame rate worth running the pipeline at) is 4.63m of genuine travel per
// frame; 7.0m gives that worst case a ~1.5x margin (~2.5x at 25 fps, ~3x at
// 30 fps), so no physically possible vehicle motion is ever rejected while
// any step beyond it can only be a detection error. Rejection is measured
// against the last ACCEPTED sample, not the last raw (seen) one: against a
// single outlier the raw variant would also recover (losing two frames --
// the outlier and the one good frame measured against it), but it accepts
// the SECOND of two consecutive outliers at the same wrong location, since
// that one lands within threshold of the first; measuring against the last
// accepted sample rejects the whole burst.
export const SPEED_MAX_STEP_M = 7.0;

// --- Incident detection (trafficlens.analytics.incidents) ---------------------
// All tunables of the stopped-vehicle detector live here so the later
// TypeScript mirror reads the exact same values; incidents.py itself
// contains no numeric tunables.

// Speed, in km/h, below which (strictly) a calibrated track counts as
// stationary for stopped-vehicle detection. The speed estimator's per-axis
// least-squares fit gives a genuinely stopped vehicle a measured noise
// floor below 1.0 km/h at 2 cm of plane-space anchor jitter (see
// tests/test_speed.py: the stopped-vehicle jitter test asserts < 1.0), so
// 3.0 sits a 3x margin above that floor -- anchor noise alone can never
// push a stopped vehicle over the threshold and suppress its incident --
// while staying below even the slowest genuine creep (walking pace is
// ~5 km/h), so a queue inching forward does not read as stopped.
export const INCIDENT_STOPPED_SPEED_KMH = 3.0;

// Continuous seconds a track's calibrated speed must stay below
// INCIDENT_STOPPED_SPEED_KMH before ONE stopped-vehicle incident fires.
// 10 s clears ordinary give-way pauses, queue creep gaps, and hesitation
// stops -- which last a few seconds -- while catching a breakdown or
// obstruction well before it has held traffic for a full signal cycle.
// Deliberately user-tunable per deployment: a motorway operator may want
// less, a junction camera more.
export const INCIDENT_MIN_STOPPED_S = 10.0;

// --- Benchmark baselines (trafficlens.bench.baselines) ------------------------
// Defaults of the standard-failure-mode baselines the engine is measured
// against. Each is set to the value that makes its baseline as STRONG as
// that baseline can honestly be: a benchmark won against a deliberately
// mis-tuned contender measures nothing. Only the tunables that have no
// engine equivalent live here -- the baselines take max_age, min_hits and
// the birth confidence straight from the TRACK_* values above, so track
// lifetime can never be the source of a measured difference.
//
// The reference view for all three is the 640x480 motorway framing the
// shipped config's gates are drawn on, where a car box is roughly 60x80 px
// and a vehicle near the gate line advances a few pixels per frame.

// Half-width, in pixels, of the band around the gate line that
// trafficlens.bench.baselines.BandCounter and PerFrameCounter treat as
// "on the gate". 20 px is about a quarter of a near-field car box and
// roughly five frames of dwell at the ~4 px/frame a vehicle crosses the
// reference gate at -- wide enough that ordinary motion cannot step clean
// over it (a narrower band would make the miss failure mode dominate and
// the baseline artificially weak), narrow enough that it does not swallow
// a quarter of the frame's near field and phantom-fire on everything that
// comes near. The band's two failure modes are inherent to the rule and
// survive any choice of this value: a smaller band misses faster
// vehicles, a larger one fires on more objects that never cross.
export const BASELINE_BAND_PX = 20.0;

// Maximum centroid displacement, in pixels, that
// trafficlens.bench.baselines.CentroidTracker will associate a detection
// to a track across. 60 px is under the centroid gap between two vehicles
// following in one lane on the reference view (about a vehicle length,
// 80 px and up near the camera), so the radius does not routinely reach
// the wrong vehicle, while still admitting a full frame of genuine
// near-field motion. Without a motion model the radius has to be measured
// from the last OBSERVED centroid rather than a predicted one, which is
// precisely why no single value can both admit fast motion and exclude a
// neighbouring vehicle.
export const BASELINE_CENTROID_MAX_DISTANCE_PX = 60.0;

// IoU floor for association in trafficlens.bench.baselines.GreedyIoUTracker.
// 0.3 is SORT's published iou_threshold. It is deliberately far looser
// than the engine's TRACK_MATCH_IOU of 0.8: the engine compares a
// detection against a Kalman-PREDICTED box, which a genuine continuation
// overlaps almost entirely, while a tracker with no motion model compares
// against the last OBSERVED box, which ordinary motion has already moved
// away from. Holding this baseline to 0.8 would reject ordinary traffic
// and make it a straw man rather than a baseline.
export const BASELINE_GREEDY_IOU_THRESH = 0.3;
